TWComponent.script:
tw.local.sql = "SELECT ID, ACCOUNTNO, REFERENCENO, POSTINGDATE, VALUEDATE, TRANSACTIONAMOUNT, AMOUNTLINKEDINBPM, AMOUNTFORCURRENTREQ, AMOUNTINREQCURRENCY FROM "+tw.env.LKP_DB_Schema+".odc_fctransaction where requesrid = ? ";

tw.local.sqlParameters = new tw.object.listOf.SQLParameter();
tw.local.sqlParameters[0] =  new tw.object.SQLParameter();
tw.local.sqlParameters[0].value = tw.local.requestId;

//tw.local.odcRequest = {};
//tw.local.odcRequest.FinancialDetailsFO ={};
tw.local.odcRequest.FinancialDetailsFO.multiTenorDates = new tw.object.listOf.MultiTenorDates();

if(tw.local.sqlResults.listLength > 0)
{
	for(var i =0; i<tw.local.sqlResults[0].rows.listLength ; i++)
	{
		tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i]  = new tw.object.MultiTenorDates();
		tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].date     = tw.local.sqlResults[0].rows[i].data[1];
		tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].amount       = tw.local.sqlResults[0].rows[i].data[0];
	}

}

